// Lightweight gallery script
// Fetches /gallery_index.json (generated by build.py) and renders a thumbnail grid.
// Clicking a thumbnail opens a simple lightbox with next/prev and keyboard support.

document.addEventListener('DOMContentLoaded', () => {
  const grid = document.getElementById('gallery-grid');
  if (!grid) return;

  fetch('/gallery_index.json')
    .then(res => res.json())
    .then(images => {
      if (!images || !images.length) {
        grid.innerHTML = '<p style="color:#ccc">No images found.</p>';
        return;
      }

      images.forEach((src, idx) => {
        const btn = document.createElement('button');
        btn.className = 'gallery-item';
        btn.setAttribute('data-index', idx);
        btn.setAttribute('aria-label', `Open image ${idx + 1}`);

        const img = document.createElement('img');
        img.src = src;
        img.alt = `Gallery image ${idx + 1}`;

        btn.appendChild(img);
        grid.appendChild(btn);

        btn.addEventListener('click', () => openLightbox(images, idx));
      });
    })
    .catch(err => {
      console.error('Failed to load gallery index:', err);
      grid.innerHTML = '<p style="color:#ccc">Unable to load gallery.</p>';
    });
});

function openLightbox(images, startIndex) {
  let index = startIndex;

  const overlay = document.createElement('div');
  overlay.className = 'lightbox-overlay';

  const imgWrap = document.createElement('div');
  imgWrap.className = 'lightbox-content';

  const img = document.createElement('img');
  img.className = 'lightbox-img';
  img.src = images[index];
  img.alt = `Image ${index + 1}`;

  const prev = document.createElement('button');
  prev.className = 'lightbox-prev';
  prev.innerHTML = '&#10094;';
  prev.addEventListener('click', () => { index = (index - 1 + images.length) % images.length; img.src = images[index]; });

  const next = document.createElement('button');
  next.className = 'lightbox-next';
  next.innerHTML = '&#10095;';
  next.addEventListener('click', () => { index = (index + 1) % images.length; img.src = images[index]; });

  const close = document.createElement('button');
  close.className = 'lightbox-close';
  close.innerHTML = '&times;';
  close.addEventListener('click', () => document.body.removeChild(overlay));

  imgWrap.appendChild(prev);
  imgWrap.appendChild(img);
  imgWrap.appendChild(next);
  imgWrap.appendChild(close);

  overlay.appendChild(imgWrap);
  document.body.appendChild(overlay);

  function onKey(e) {
    if (e.key === 'Escape') document.body.removeChild(overlay);
    if (e.key === 'ArrowLeft') { index = (index - 1 + images.length) % images.length; img.src = images[index]; }
    if (e.key === 'ArrowRight') { index = (index + 1) % images.length; img.src = images[index]; }
  }

  overlay.addEventListener('click', (ev) => {
    if (ev.target === overlay) document.body.removeChild(overlay);
  });

  document.addEventListener('keydown', onKey, { once: true });
}
